// @generated by:gauntlet run:godseye-local-delivery
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type DeliveryFixture, deliveryFixture } from "./delivery-helpers.js";

describe("current policy checks and eligible immutable rollback", () => {
  let fixture: DeliveryFixture;
  beforeEach(async () => {
    fixture = await deliveryFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  it.each(["release", "rollback"] as const)(
    "T-AC-46 T-AC-48 refuses retained %s evidence that lacks the current policy's additional required check",
    async (intent) => {
      const old = await fixture.createPolicy(),
        ci = await fixture.push(),
        built = await fixture.build(old.id, ci.id),
        active = await fixture.release(old.id, ci.id, built.artifact.id);
      await fixture.infrastructure.delivery.revokePolicy(
        fixture.freshOwner(),
        old.id,
        old.revision,
        randomUUID(),
      );
      const current = await fixture.createPolicy({ requiredChecks: ["test", "security-extra"] });
      await expect(
        fixture.prepare({
          policyId: current.id,
          ciRunId: ci.id,
          intent,
          ...(intent === "release"
            ? { artifactId: built.artifact.id }
            : { deploymentId: active.run.id }),
        }),
      ).rejects.toMatchObject({ code: "ARTIFACT_REJECTED" });
      expect(fixture.provider.active.get(fixture.development.id)).toBe(built.artifact.digest);
      expect(fixture.provider.effects.filter((effect) => effect.action === "promote")).toHaveLength(
        1,
      );
    },
  );
  it("T-AC-48 restages an eligible retained artifact under fresh exact rollback authority without rewinding database data", async () => {
    const policy = await fixture.createPolicy(),
      first = await fixture.push(),
      a = await fixture.build(policy.id, first.id),
      releaseA = await fixture.release(policy.id, first.id, a.artifact.id);
    fixture.source.head = "b".repeat(40);
    const second = await fixture.push(),
      b = await fixture.build(policy.id, second.id);
    await fixture.release(policy.id, second.id, b.artifact.id);
    const before = await fixture.store.db.select().from(schema.databaseAllocations);
    const preparation = await fixture.prepare({
        policyId: policy.id,
        ciRunId: second.id,
        intent: "rollback",
        deploymentId: releaseA.run.id,
      }),
      run = await fixture.admit(preparation);
    await fixture.infrastructure.foundation.tick("exact-rollback-worker");
    expect(
      (await fixture.infrastructure.delivery.overview(fixture.freshOwner())).deployments.find(
        (item) => item.id === run.id,
      )?.state,
    ).toBe("active");
    expect(fixture.provider.active.get(fixture.development.id)).toBe(a.artifact.digest);
    expect(await fixture.store.db.select().from(schema.databaseAllocations)).toEqual(before);
    expect(
      (await fixture.infrastructure.delivery.overview(fixture.freshOwner())).artifacts,
    ).toHaveLength(2);
  });
  it("T-AC-48 rechecks current-policy artifact configuration after preparation before any staging effect", async () => {
    const policy = await fixture.createPolicy(),
      ci = await fixture.push(),
      built = await fixture.build(policy.id, ci.id),
      preparation = await fixture.prepare({
        policyId: policy.id,
        ciRunId: ci.id,
        intent: "release",
        artifactId: built.artifact.id,
      });
    const [row] = await fixture.store.db
      .select()
      .from(schema.deliveryArtifacts)
      .where(eq(schema.deliveryArtifacts.id, built.artifact.id));
    if (!row) throw new Error("Immutable delivery artifact missing");
    await fixture.store.db
      .update(schema.deliveryArtifacts)
      .set({ providerEvidence: { ...row.providerEvidence, configurationHash: "f".repeat(64) } })
      .where(eq(schema.deliveryArtifacts.id, row.id));
    const run = await fixture.admit(preparation);
    await fixture.infrastructure.foundation.tick("artifact-drift-worker");
    expect(
      (await fixture.infrastructure.delivery.overview(fixture.freshOwner())).deployments.find(
        (item) => item.id === run.id,
      )?.state,
    ).not.toBe("active");
    expect(fixture.provider.effects.map((effect) => effect.action)).toEqual(["build"]);
  });
});
